import { Carousel } from '@daisforge/ui';
import styled from 'styled-components';
export function App() {
    const StyledCard = styled.div`
        display: flex;
        align-items: center;
        justify-content: center;
        border: 1px solid #d6d6d6;
        border-radius: 12px;
        width: 320px;
        height: 180px;
        background-color: #f4f5f7;
        color: #1b1f23;
        font-size: 20px;
        font-weight: 600;
