    return (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
            <NumberFormat
                size="s"
                defaultValue="-123"
                thousandSeparator=" "
                decimalSeparator="."
                allowNegative
            />
        </div>
    );
}

